-- Chromebook edition of the AerisOS config: same look and keys, lighter programs
-- (kitty, Firefox, Waybar, wofi) and no blur, shadows or animations.

---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "thunar"
local menu = "wofi --show drun"
local tui  = "kitty --class aeris.tui-float -e "   -- small floating terminal panel


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("dunst")   -- start first, so it owns notifications instead of the Xfce daemon
    hl.exec_cmd("waybar")
    hl.exec_cmd("hypridle")   -- dim, lock and screen-off rules (hypridle.conf)
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)


