-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


-- Small floating window for terminal panels (wiremix, bluetui, nmtui)
hl.window_rule({
    name  = "tui-float",
    match = { class = "^aeris\\.tui-float$" },

    float = true,
    size  = "900 560",
    center = true,
})
